mapper.select:
SELECT o.id, o.order_no as orderNo, o.user_id as userId, o.vehicle_id as vehicleId, o.technician_id as technicianId, CAST(o.status AS SIGNED) as status, o.total_amount as totalAmount, o.labor_cost as laborCost, o.parts_cost as partsCost, o.payment_status as paymentStatus, o.actual_hours as actualHours, o.fault_desc as faultDesc, o.create_time as createTime, o.update_time as updateTime, u.real_name as customerName, u.phone as customerPhone, t.real_name as technicianName, v.plate_number as plateNumber, v.brand as vehicleBrand, v.model as vehicleModel FROM biz_repair_order o LEFT JOIN sys_user u ON o.user_id = u.id LEFT JOIN sys_user t ON o.technician_id = t.id LEFT JOIN biz_vehicle v ON o.vehicle_id = v.id WHERE 1=1
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.status = #{status}
AND o.technician_id = #{technicianId}
ORDER BY o.create_time DESC
